<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Şirket Yönetim Merkezi V7</title>
<style>
:root{color-scheme:dark;--bg:#040812;--p:#0b1525;--p2:#101e33;--l:#263c5c;--t:#eef6ff;--m:#91a8c5;--g:#42e1a0;--b:#62a8ff;--r:#ff6b7d;--y:#ffd166;--v:#ba8cff;--s:0 16px 50px #0009}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#12305a 0,transparent 32%),radial-gradient(circle at 92% 0,#321b58 0,transparent 28%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}button,input,select{font:inherit}.shell{max-width:2200px;margin:auto}.top{position:sticky;top:5px;z-index:30;display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 15px;border:1px solid var(--l);border-radius:16px;background:#081322ef;box-shadow:var(--s)}.brand{font-size:19px;font-weight:1000}.brand small{display:block;color:var(--m);font-size:9px;margin-top:3px;font-weight:500}.status,.tabs,.tags,.row{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.status{justify-content:flex-end}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.pill b{color:var(--t)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--r);margin-right:5px}.dot.ok{background:var(--g);box-shadow:0 0 12px var(--g)}.hidden,[hidden]{display:none!important}.login{max-width:440px;margin:10vh auto;padding:24px;border:1px solid var(--l);border-radius:18px;background:var(--p);box-shadow:var(--s)}button{cursor:pointer;border:0;border-radius:8px;padding:8px 11px;background:var(--g);color:#032018;font-weight:900}button:disabled{opacity:.42;cursor:not-allowed}.secondary{background:#203653;color:var(--t)}.danger{background:var(--r);color:#fff}.small{font-size:9px;padding:6px 8px}.full{width:100%;margin-top:9px}.tabs{margin:11px 0}.tab{background:#0a1628;color:var(--m);border:1px solid var(--l);border-radius:999px}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.ticker{overflow:hidden;border:1px solid #755b25;background:linear-gradient(90deg,#21170b,#191424,#21170b);border-radius:11px;margin:10px 0;white-space:nowrap}.tickerTrack{display:inline-block;padding:9px 0;animation:ticker 38s linear infinite;font-size:10px;font-weight:800;color:var(--y)}@keyframes ticker{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}.banner,.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.banner{border-color:#6d592b;color:var(--y);background:#211d12}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.metrics{display:grid;grid-template-columns:repeat(8,minmax(120px,1fr));gap:8px}.metric,.item{padding:10px;border:1px solid var(--l);border-radius:11px;background:linear-gradient(180deg,var(--p2),#091423)}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:6px;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.panel{display:grid;gap:10px}.card{padding:12px;border:1px solid var(--l);border-radius:14px;background:linear-gradient(180deg,#101b2eeb,#08101deb);box-shadow:var(--s);overflow:hidden}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:9px}.title h2{margin:0;font-size:15px}.item h3{margin:0 0 4px;font-size:13px}.item p{margin:4px 0;color:var(--m);font-size:9px}.row{justify-content:space-between}label{display:block;color:var(--m);font-size:9px}input,select{display:block;width:100%;margin-top:4px;padding:8px;border:1px solid var(--l);border-radius:8px;background:#06111f;color:var(--t)}.form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:end;margin-top:8px}.tablewrap{overflow:auto;max-height:680px;overscroll-behavior:contain}table{width:100%;border-collapse:collapse;min-width:1050px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;font-size:8px;text-transform:uppercase;border-bottom:1px solid var(--l);z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.num{text-align:right}.bar{height:7px;background:#152239;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.event,.tx,.news{padding:8px 0;border-bottom:1px solid var(--l);font-size:9px}.tx{display:grid;grid-template-columns:55px 120px 1fr auto;gap:7px}.news strong{font-size:11px}.chart{width:100%;height:240px;border:1px solid var(--l);border-radius:10px;background:#060d19}.legend{display:flex;gap:12px;flex-wrap:wrap;color:var(--m);font-size:9px}.sw{display:inline-block;width:9px;height:9px;border-radius:3px;margin-right:4px}.score{font-size:38px;font-weight:1000}.score.a{color:var(--g)}.score.b{color:var(--b)}.score.c{color:var(--y)}.score.d{color:var(--r)}.busy{position:fixed;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,var(--g),var(--b),var(--v));transform:scaleX(0);transform-origin:left;z-index:100}.busy.on{transform:scaleX(1)}#toast{position:fixed;right:12px;bottom:12px;max-width:520px;z-index:90;background:#10243b;box-shadow:var(--s)}@media(max-width:1600px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:950px){body{padding:5px}.top{position:static;flex-direction:column;align-items:flex-start}.status{justify-content:flex-start}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.grid3,.grid4,.form{grid-template-columns:1fr}}
</style></head><body><div id="busy" class="busy"></div><div class="shell"><header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ V7<small>Tick muhasebesi · kredi notu · SLA uygunluğu · kalıcı ticari yönetim</small></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="conn">BAĞLANTI YOK</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panelName">Genel</b></span><span class="pill">Son veri <b id="updated">—</b></span><button id="logout" class="secondary small hidden">Çıkış</button></div></header><section id="loginView" class="login"><h1>Şirket hesabına giriş</h1><p class="sub">Motor; fiyat, kapasite, banka, muhasebe ve dağıtım kayıtlarının kalıcı otoritesidir.</p><label>Kullanıcı adı<input id="username"></label><label>Parola<input id="password" type="password"></label><button id="login" class="full">Giriş yap</button><div id="loginMsg" class="notice">Geçici hesap bilgileri motor konsolunda görünür.</div></section><main id="app" class="hidden"><div id="ticker" class="ticker"><div class="tickerTrack">Haber bülteni hazırlanıyor…</div></div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"><button class="tab active" data-panel="overview">Genel</button><button class="tab" data-panel="finance">Gelir & Gider</button><button class="tab" data-panel="services">Hizmetler & Kapasite</button><button class="tab" data-panel="products">Ürünler & Dağıtım</button><button class="tab" data-panel="infra">Altyapı</button><button class="tab" data-panel="bank">Banka</button><button class="tab" data-panel="protocols">Protokoller</button><button class="tab" data-panel="contracts">SLA</button><button class="tab" data-panel="news">Haberler</button><button class="tab" data-panel="account">Hesap</button></nav><section id="overview" class="panel"></section><section id="finance" class="panel" hidden></section><section id="services" class="panel" hidden></section><section id="products" class="panel" hidden></section><section id="infra" class="panel" hidden></section><section id="bank" class="panel" hidden></section><section id="protocols" class="panel" hidden></section><section id="contracts" class="panel" hidden></section><section id="news" class="panel" hidden></section><section id="account" class="panel" hidden></section></main></div><div id="toast" class="notice hidden"></div>
<script>
'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const S={d:null,active:'overview',loading:false,busy:false,timer:null,pending:null,drafts:new Map(),toastTimer:null};
const field=(k,v,t='number',a='')=>`<input data-key="${esc(k)}" type="${t}" value="${esc(S.drafts.has(k)?S.drafts.get(k):v??'')}" ${a}>`;const sel=(k,v,opts)=>{const x=String(S.drafts.has(k)?S.drafts.get(k):v??'');return `<select data-key="${esc(k)}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===x?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`};
function panel(id){const t=document.getElementById(id)||$('#overview');S.active=t.id;$$('.panel').forEach(p=>p.hidden=p!==t);$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.panel===t.id));$('#panelName').textContent=document.querySelector(`.tab[data-panel="${t.id}"]`)?.textContent||t.id;history.replaceState(null,'',`#${t.id}`)}$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-panel]');if(b){e.preventDefault();panel(b.dataset.panel)}});
function editing(){return S.busy||!!document.activeElement?.matches('input,select,textarea')}function toast(t,ok=true){const e=$('#toast');clearTimeout(S.toastTimer);e.textContent=t;e.className=`notice ${ok?'good':'bad'}`;e.classList.remove('hidden');S.toastTimer=setTimeout(()=>e.classList.add('hidden'),5500)}async function req(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{d={basarili:false,aciklama:'Yanıt okunamadı.'}}if(!r.ok||d.basarili===false)throw new Error(d.aciklama||`HTTP ${r.status}`);return d}
function showApp(){$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');panel(location.hash.slice(1)||'overview')}async function login(){try{const r=await req('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});showApp();toast(r.aciklama);await refresh(true);poll()}catch(e){$('#loginMsg').textContent=e.message;$('#loginMsg').className='notice bad'}}async function logout(){try{await req('/api/cikis',{})}catch{}location.reload()}function poll(){clearInterval(S.timer);S.timer=setInterval(()=>refresh(false),1000)}async function refresh(force=false){if(S.loading)return;S.loading=true;try{const d=await req(`/api/durum?t=${Date.now()}`);S.d=d;$('#dot').classList.add('ok');$('#conn').textContent='CANLI';$('#tick').textContent=d.tickNumarasi||d.muhasebeV7?.sonTick?.tickNumarasi||0;$('#updated').textContent=new Date().toLocaleTimeString('tr-TR');renderMetrics(d);renderTicker(d);if(force||!editing()){S.pending=null;renderAll(d)}else S.pending=d}catch(e){$('#dot').classList.remove('ok');$('#conn').textContent='HATA';if(e.message.includes('Oturum'))location.reload()}finally{S.loading=false}}
function latest(d){return d.muhasebeV7?.sonTick||{}}function renderMetrics(d){const s=d.sirket||{},i=d.isletim||{},m=latest(d),b=d.bankaV7||{},v=d.v6Sirket||{};const a=[['Kasa',money(s.kasa)],['Tick gelir',money(m.toplamGelir)],['Tick gider',money(m.toplamGider)],['Tick net',money(m.tickNetKazanc)],['Kredi notu',`${int(b.krediNotu)} · ${esc(b.krediNotuSinifi||'—')}`],['Toplam borç',money(b.aktifBorc)],['Gerçek kapasite',int(v.gercekKapasiteBirimi)],['Kullanılan kapasite',int(v.kullanilanKapasiteBirimi)],['Aktif kullanıcı',int(i.toplamAboneSayisi)],['Şirket değeri',money(i.sirketDegeri)],['Operasyon riski',num(i.operasyonRiski)],['Ödenemeyen',money(i.odenemeyenGider)]];$('#metrics').innerHTML=a.map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function renderTicker(d){const h=(d.haberBulteni||[]).slice(0,12);$('.tickerTrack').innerHTML=h.length?h.map(x=>`★ T${int(x.tickNumarasi)} · ${esc(x.sirketAdi||'Piyasa')} · ${esc(x.baslik)} — ${esc(x.ozet)}`).join(' &nbsp;&nbsp;&nbsp; ◆ &nbsp;&nbsp;&nbsp; '):'★ Şirket operasyonları normal seyrediyor.'}
function renderAll(d){overview(d);finance(d);services(d);products(d);infra(d);bank(d);protocols(d);contracts(d);news(d);account(d);panel(S.active)}
function overview(d){const s=d.sirket||{},i=d.isletim||{},m=latest(d),b=d.bankaV7||{},v=d.v6Sirket||{},events=(i.sonOlaylar||[]).slice(0,12).map(o=>`<div class="event"><div class="row"><b class="${o.olumlu?'good':'bad'}">${esc(o.baslik)}</b><span>T${int(o.tickNumarasi)}</span></div><p>${esc(o.aciklama)}</p></div>`).join('')||'<div class="notice">Olay yok.</div>';$('#overview').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Bu tickin özeti</h2><span class="tag ${Number(m.tickNetKazanc)>=0?'good':'bad'}">${money(m.tickNetKazanc)}</span></div><div class="grid4">${[['Brüt gelir',money(m.toplamGelir)],['Toplam gider',money(m.toplamGider)],['Nakit değişimi',money(m.nakitDegisimi)],['Kurtarma kredisi',money(m.kurtarmaKredisiGirisi)],['Kapanış kasası',money(m.kapanisKasasi)],['Borç',money(m.toplamBorc)],['Kredi notu',int(m.krediNotu)],['Kapasite doluluğu',`%${num((v.kapasiteDolulukOrani||0)*100)}`]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Banka sağlığı</h2><span class="tag">${esc(b.riskDurumu||'—')}</span></div><div class="row"><div><div class="score ${(b.krediNotu||0)>=760?'a':(b.krediNotu||0)>=620?'b':(b.krediNotu||0)>=500?'c':'d'}">${int(b.krediNotu)}</div><p>Sınıf ${esc(b.krediNotuSinifi||'—')}</p></div><div><b>${money(b.kullanilabilirLimit)}</b><p>Kullanılabilir kredi limiti</p><b>${money(b.sonrakiTaksit)}</b><p>Sonraki taksit · T${int(b.sonrakiOdemeTicki)}</p></div></div></div></div><div class="grid"><div class="card"><div class="title"><h2>Son şirket olayları</h2></div>${events}</div><div class="card"><div class="title"><h2>Teknik ve ticari durum</h2></div><div class="grid4">${[['Kod kalitesi',num(s.kodKalitesiPuani)],['Performans',num(s.performansPuani)],['Güvenlik',num(s.guvenlikPuani)],['İtibar',num(s.itibarPuani)],['Teknik borç',num(i.teknikBorc)],['Bakım baskısı',num(i.bakimBaskisi)],['Ekosistem',num(i.ekosistemPuani)],['Kurtarma sayısı',int(b.kurtarmaKredisiSayisi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div></div>`}
function svgChart(rows){if(!rows.length)return'<div class="notice">Henüz tick geçmişi yok.</div>';const w=900,h=220,p=25,vals=rows.flatMap(x=>[Number(x.toplamGelir||0),Number(x.toplamGider||0),Number(x.tickNetKazanc||0)]),max=Math.max(1,...vals.map(Math.abs)),pts=(key,offset)=>rows.map((x,i)=>`${p+i*(w-2*p)/Math.max(1,rows.length-1)},${h/2-Number(x[key]||0)*(h/2-p)/max+offset}`).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="0" y1="${h/2}" x2="${w}" y2="${h/2}" stroke="#33445d"/><polyline fill="none" stroke="#42e1a0" stroke-width="3" points="${pts('toplamGelir',0)}"/><polyline fill="none" stroke="#ff6b7d" stroke-width="3" points="${pts('toplamGider',0)}"/><polyline fill="none" stroke="#62a8ff" stroke-width="3" points="${pts('tickNetKazanc',0)}"/></svg><div class="legend"><span><i class="sw" style="background:#42e1a0"></i>Gelir</span><span><i class="sw" style="background:#ff6b7d"></i>Gider</span><span><i class="sw" style="background:#62a8ff"></i>Net</span></div>`}
function finance(d){const m=latest(d),rows=(d.muhasebeV7?.tickler||[]).slice(-60);$('#finance').innerHTML=`<div class="card"><div class="title"><div><h2>Tick gelir–gider grafiği</h2><span class="sub">Yeşil gelir, kırmızı gider, mavi net sonuç. Kredi girişi gelir sayılmaz.</span></div></div>${svgChart(rows)}</div><div class="grid"><div class="card"><div class="title"><h2>Bu tick gelirleri</h2><b class="good">${money(m.toplamGelir)}</b></div>${[['Hizmet, SLA ve olay',m.hizmetSlaVeOlayGeliri],['Ürün geliri',m.urunGeliri],['Abonelik geliri (bilgi)',m.abonelikGeliriBilgi],['Protokol lisansı',m.protokolGeliri]].map(x=>`<div class="row item"><span>${x[0]}</span><b class="good">${money(x[1])}</b></div>`).join('')}</div><div class="card"><div class="title"><h2>Bu tick giderleri</h2><b class="bad">${money(m.toplamGider)}</b></div>${[['Operasyon ve altyapı',m.operasyonGideri],['Finansman/taksit',m.finansmanGideri],['Yatırım ve yayın',m.yatirimGideri],['İade/chargeback',m.iadeGideri],['Ceza',m.cezaGideri],['Yeni ödenemeyen gider',m.odenemeyenGiderArtisi]].map(x=>`<div class="row item"><span>${x[0]}</span><b class="bad">${money(x[1])}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Tick muhasebe defteri</h2><span class="tag">Son ${rows.length} tick</span></div><div class="tablewrap" data-scroll-key="finance"><table><thead><tr><th>Tick</th><th class="num">Gelir</th><th class="num">Gider</th><th class="num">Net</th><th class="num">Nakit değişimi</th><th class="num">Kasa</th><th class="num">Borç</th><th class="num">Not</th></tr></thead><tbody>${[...rows].reverse().map(x=>`<tr><td>T${int(x.tickNumarasi)}</td><td class="num good">${money(x.toplamGelir)}</td><td class="num bad">${money(x.toplamGider)}</td><td class="num ${Number(x.tickNetKazanc)>=0?'good':'bad'}"><b>${money(x.tickNetKazanc)}</b></td><td class="num">${money(x.nakitDegisimi)}</td><td class="num">${money(x.kapanisKasasi)}</td><td class="num">${money(x.toplamBorc)}</td><td class="num">${int(x.krediNotu)}</td></tr>`).join('')}</tbody></table></div></div>`}
function serviceList(){return S.d?.kodTabanliYayinlar?.hizmetler||[]}function services(d){const hs=serviceList();$('#services').innerHTML=`<div class="card"><div class="title"><div><h2>Kalıcı hizmet fiyatı ve kapasite tahsisi</h2><span class="sub">Sunucu manifesti ilk varsayılandır; burada değişen değer motor kaydında üstün kalır.</span></div></div><div class="tablewrap" data-scroll-key="services"><table><thead><tr><th>Hizmet</th><th>Durum</th><th class="num">Fiyat</th><th class="num">Baz</th><th class="num">Satın</th><th class="num">Yatırım</th><th class="num">Etkin</th><th>İşlem</th></tr></thead><tbody>${hs.map(h=>{const id=`${h.hizmetKimligi}@${h.hizmetSurumu}`;return `<tr><td><b>${esc(h.hizmetKimligi)}</b><div class="sub">v${esc(h.hizmetSurumu)}</div></td><td class="${h.aktif?'good':'bad'}">${h.aktif?'AKTİF':'PASİF'}</td><td class="num">${field(`svc:${id}:price`,h.birimFiyat,'number','min="0.01"')}</td><td class="num">${int(h.bazKapasite)}</td><td class="num">${int(h.satinAlinanKapasite)}</td><td class="num">${int(h.yatirimBonusu)}</td><td class="num"><b>${int(h.etkinKapasite)}</b></td><td><button class="small" data-action="service-price" data-id="${esc(id)}">Fiyat</button> <button class="small secondary" data-action="service-toggle" data-id="${esc(id)}">${h.aktif?'Kapat':'Aç'}</button><div class="row"><span>${field(`svc:${id}:cap`,1,'number','min="1" max="500"')}</span><button class="small" data-action="service-cap" data-id="${esc(id)}">Tahsis al</button></div></td></tr>`}).join('')}</tbody></table></div></div>`}
function distributionMap(d){return new Map((d.ekosistem?.dagitimAyarlari||[]).map(x=>[x.urunKimligi,x.ayar||{}]))}function osOptions(d){return [['','İşletim sistemi seç']].concat((d.ekosistem?.isletimSistemleri||[]).map(x=>[x.uygulamaKimligi,`${x.uygulamaAdi} · ${x.sirketAdi}`]))}function protocolOptions(d){const own=(d.kodTabanliYayinlar?.protokoller||[]).filter(x=>x.piyasada).map(x=>[x.protokol?.protokolKimligi,`${x.protokol?.protokolAdi} (kendi)`]),market=(d.protokoller||[]).map(x=>[x.protokolKimligi,`${x.protokolAdi} (piyasa)`]);return [...new Map([['','Protokol seç'],...own,...market]).entries()]}
function products(d){const apps=d.kodTabanliYayinlar?.uygulamalar||[],ps=d.isletim?.urunler||[],dm=distributionMap(d),os=osOptions(d),protos=protocolOptions(d);$('#products').innerHTML=`<div class="card"><div class="title"><h2>Kodlanan ürünler</h2></div>${apps.map(x=>appCard(x)).join('')||'<div class="notice">Manifest yok.</div>'}</div><div class="card"><div class="title"><h2>Piyasadaki ürünler ve dağıtım</h2></div>${ps.map(p=>productCard(p,dm.get(p.urunKimligi)||{},os,protos)).join('')||'<div class="notice">Ürün yok.</div>'}</div>`}
function appCard(x){const a=x.uygulama||{},v=x.dogrulama||{},id=a.uygulamaKimligi;return `<div class="item" style="margin-bottom:8px"><div class="row"><div><h3>${esc(a.uygulamaAdi)} <span class="tag">${esc(a.kategori)}</span></h3><p>${esc(a.aciklama)}</p></div><span class="tag ${v.gecerli?'good':'bad'}">${v.gecerli?'GEÇERLİ':'EKSİK'}</span></div>${x.piyasada?'<div class="notice good">Piyasada</div>':`<div class="form"><label>Model${sel(`app:${id}:model`,'abonelik',[['abonelik','Abonelik'],['kullanim','Kullanım'],['freemium','Freemium'],['lisans','Lisans']])}</label><label>Abonelik${field(`app:${id}:sub`,25,'number','min="0"')}</label><label>Kullanım${field(`app:${id}:use`,0,'number','min="0"')}</label><button data-action="app-publish" data-id="${esc(id)}" ${!v.gecerli?'disabled':''}>Piyasaya aç</button></div>`}</div>`}
function productCard(p,a,os,protos){const id=p.urunKimligi,isOS=p.urunTuru==='isletim-sistemi',occ=Number(p.kullaniciKapasitesi)>0?Number(p.aktifKullaniciSayisi)*100/Number(p.kullaniciKapasitesi):0;return `<div class="item" style="margin-bottom:8px"><div class="row"><div><h3>${esc(p.urunAdi)} <span class="tag">${esc(p.urunTuru||p.kategori)}</span></h3><p>${int(p.aktifKullaniciSayisi)} / ${int(p.kullaniciKapasitesi)} kullanıcı · %${num(occ)}</p></div><span class="tag ${p.aktif?'good':'bad'}">${p.aktif?'AKTİF':'PASİF'}</span></div><div class="bar"><i style="width:${Math.min(100,occ)}%"></i></div><div class="form"><label>İşletim sistemi${isOS?'<input value="Kendisi işletim sistemi" disabled>':sel(`dist:${id}:os`,a.isletimSistemiKimligi||'',os)}</label><label>Protokol${sel(`dist:${id}:proto`,a.baglantiProtokoluKimligi||'',protos)}</label><label>Durum${sel(`dist:${id}:active`,String(a.elleAktifOlmasiIsteniyor??p.aktif),[['true','Aktif'],['false','Pasif']])}</label><button data-action="distribution" data-id="${esc(id)}">Dağıtımı kaydet</button></div><div class="form"><label>Abonelik${field(`prd:${id}:sub`,p.abonelikUcreti,'number','min="0"')}</label><label>Kullanım${field(`prd:${id}:use`,p.kullanimBasinaUcret,'number','min="0"')}</label><label>Tahsis ekle${field(`prd:${id}:cap`,100,'number','min="50" max="100000"')}</label><div><button class="small" data-action="product-save" data-id="${esc(id)}">Fiyat</button> <button class="small secondary" data-action="product-cap" data-id="${esc(id)}">Kapasite</button></div></div></div>`}
function infra(d){const l=d.ekosistem?.altyapiSinirlari||{},v=d.v6Sirket||{},list=d.yatirimMagazasi||[];$('#infra').innerHTML=`<div class="card"><div class="title"><h2>Gerçek fiziksel kapasite havuzu</h2></div><div class="grid4">${[['Gerçek havuz',int(v.gercekKapasiteBirimi)],['Tahsis edilen',int(v.tahsisEdilenKapasiteBirimi)],['Anlık kullanılan',int(v.kullanilanKapasiteBirimi)],['Doluluk',`%${num((v.kapasiteDolulukOrani||0)*100)}`],['Aktif iş',int(l.mevcutAktifIs)],['Kuyruk',int(l.kuyrukUzunlugu)],['Aktif kullanıcı',int(l.mevcutAktifKullanici)],['Birleşik yük',`%${num((l.birlesikYukOrani||0)*100)}`]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Yatırımlar</h2></div><div class="grid4">${list.map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.aciklama)}</p><div class="tags"><span class="tag good">Seviye ${int(x.seviye)}</span><span class="tag warn">${money(x.tickBakimGideri)}/tick</span></div><div class="row"><b>${money(x.sonrakiMaliyet)}</b><button class="small" data-action="investment" data-id="${esc(x.yatirimTuru)}">Satın al</button></div></div>`).join('')}</div></div>`}
function bank(d){const b=d.bankaV7||{},packs=d.krediPaketleri||[],loans=d.isletim?.krediler||[];$('#bank').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Kredi notu ve limit</h2><span class="tag ${Number(b.krediNotu)>=650?'good':Number(b.krediNotu)>=500?'warn':'bad'}">${esc(b.riskDurumu||'—')}</span></div><div class="row"><div class="score ${(b.krediNotu||0)>=760?'a':(b.krediNotu||0)>=620?'b':(b.krediNotu||0)>=500?'c':'d'}">${int(b.krediNotu)}<small>${esc(b.krediNotuSinifi||'')}</small></div><div><p>Toplam limit</p><b>${money(b.tahminiKrediLimiti)}</b><p>Kullanılabilir</p><b>${money(b.kullanilabilirLimit)}</b></div></div><div class="grid4">${[['Aktif borç',money(b.aktifBorc)],['Sonraki taksit',money(b.sonrakiTaksit)],['Ödeme ticki',`T${int(b.sonrakiOdemeTicki)}`],['Faiz çarpanı',`×${num(b.piyasaFaizCarpani)}`],['Aktif kredi',int(b.aktifKrediSayisi)],['Temerrüt',int(b.temerrutSayisi)],['Kurtarma kredisi',int(b.kurtarmaKredisiSayisi)],['Not sınıfı',esc(b.krediNotuSinifi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Kredi paketleri</h2></div>${packs.map(p=>`<div class="item"><h3>${esc(p.ad)}</h3><p>${money(p.asgariTutar)}–${money(p.azamiTutar)} · Not ≥ ${int(p.asgariKrediNotu)} · Tick faiz %${num(Number(p.tickFaizOrani)*100)}</p><label>Tutar${field(`loan:${p.krediTuru}`,p.asgariTutar,'number',`min="${p.asgariTutar}" max="${p.azamiTutar}"`)}</label><button class="full" data-action="loan" data-id="${esc(p.krediTuru)}">Kredi çek</button></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Mevcut krediler</h2></div><div class="tablewrap"><table><thead><tr><th>Tür</th><th class="num">Ana para</th><th class="num">Kalan borç</th><th class="num">Taksit</th><th class="num">Faiz/tick</th><th class="num">Kalan taksit</th><th class="num">Sonraki tick</th><th>Durum</th></tr></thead><tbody>${loans.map(l=>`<tr><td><b>${esc(l.krediTuru)}</b></td><td class="num">${money(l.anaPara)}</td><td class="num">${money(l.kalanBorc)}</td><td class="num">${money(l.taksitTutari)}</td><td class="num">%${num(Number(l.tickFaizOrani)*100)}</td><td class="num">${int(l.kalanTaksit)}</td><td class="num">T${int(l.sonrakiOdemeTicki)}</td><td class="${l.aktif?'warn':'good'}">${l.aktif?'AKTİF':'KAPANDI'}</td></tr>`).join('')||'<tr><td colspan="8">Kredi yok.</td></tr>'}</tbody></table></div></div>`}
function protocols(d){const own=d.kodTabanliYayinlar?.protokoller||[],market=d.protokoller||[];$('#protocols').innerHTML=`<div class="grid"><div class="card"><h2>Kodlanan protokoller</h2>${own.map(x=>{const p=x.protokol||{},id=`${p.protokolKimligi}@${p.surum}`;return `<div class="item"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><span class="tag ${x.gecerli?'good':'bad'}">${x.gecerli?'GEÇERLİ':'EKSİK'}</span></div>${x.piyasada?'<div class="notice good">Piyasada</div>':`<div class="form"><label>Lisans${sel(`proto:${id}:model`,'acik',[['acik','Açık'],['tek-seferlik','Tek seferlik'],['abonelik','Abonelik'],['karma','Karma']])}</label><label>Benimseme${field(`proto:${id}:adopt`,0)}</label><label>Tick lisansı${field(`proto:${id}:tick`,0)}</label><button data-action="protocol-publish" data-id="${esc(id)}">Yayınla</button></div>`}</div>`}).join('')}</div><div class="card"><h2>Piyasa protokolleri</h2>${market.map(p=>`<div class="item"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><button class="small" data-action="protocol-adopt" data-id="${esc(p.protokolKimligi)}">Benimse</button></div><p>${money(p.benimsemeBedeli)} + ${money(p.tickLisansBedeli)}/tick</p></div>`).join('')||'<div class="notice">Piyasa protokolü yok.</div>'}</div></div>`}
function contracts(d){const offers=d.sozlesmeTeklifleri||[],active=d.isletim?.sozlesmeler||[],map=new Map((d.slaUygunluklari||[]).map(x=>[x.teklifKimligi,x]));$('#contracts').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Açık SLA teklifleri</h2></div>${offers.map(o=>{const u=map.get(o.teklifKimligi)||{uygun:false,gerekliHizmetler:[],eksikHizmetler:[],yetersizKosullar:['Uygunluk hesaplanmadı']};return `<div class="item"><div class="row"><div><h3>${esc(o.baslik)}</h3><p>${esc(o.kategori)} · ${money(o.tickOdemesi)}/tick · Ceza ${money(o.ihlalCezasi)}</p></div><span class="tag ${u.uygun?'good':'bad'}">${u.uygun?'UYGUN':'UYGUN DEĞİL'}</span></div><div class="tags">${(u.gerekliHizmetler||[]).map(h=>`<span class="tag ${(u.eksikHizmetler||[]).includes(h)?'bad':'good'}">${esc(h)}</span>`).join('')}</div>${(u.yetersizKosullar||[]).length?`<div class="notice bad">${u.yetersizKosullar.map(esc).join(' · ')}</div>`:''}<div class="row"><span>Kapasite ${int(o.gerekliKapasite)} · K/P/G ${num(o.asgariKalite)}/${num(o.asgariPerformans)}/${num(o.asgariGuvenlik)}</span><button class="small" data-action="contract" data-id="${esc(o.teklifKimligi)}" ${u.uygun?'':'disabled'}>Kabul et</button></div></div>`}).join('')||'<div class="notice">Teklif yok.</div>'}</div><div class="card"><h2>Aktif sözleşmeler</h2>${active.map(s=>`<div class="item"><b>${esc(s.baslik)}</b><p>Başarı ${int(s.basariliTickSayisi)} · İhlal ${int(s.ihlalSayisi)} · Kapasite ${int(s.gerekliKapasite)} · T${int(s.bitisTicki)} bitiş</p></div>`).join('')||'<div class="notice">Sözleşme yok.</div>'}</div></div>`}
function news(d){const h=d.haberBulteni||[];$('#news').innerHTML=`<div class="card"><div class="title"><div><h2>Şirket haber bülteni</h2><span class="sub">Finansal alarm, kapasite, yatırım, uygulama ve piyasa olayları.</span></div></div>${h.map(x=>`<article class="news"><div class="row"><strong class="${x.seviye==='kritik'||x.onem==='kritik'?'bad':x.seviye==='iyi'||x.onem==='iyi'?'good':'warn'}">${esc(x.baslik)}</strong><span>T${int(x.tickNumarasi)}</span></div><p>${esc(x.ozet)}</p>${Number(x.finansalEtki)?`<b class="${Number(x.finansalEtki)>=0?'good':'bad'}">${money(x.finansalEtki)}</b>`:''}</article>`).join('')||'<div class="notice">Haber yok.</div>'}</div>`}
function account(d){const i=d.isletim||{};$('#account').innerHTML=`<div class="grid"><div class="card"><h2>Parola değiştir</h2><label>Mevcut${field('account:old','', 'password')}</label><label>Yeni${field('account:new','', 'password')}</label><button class="full" data-action="password">Değiştir</button></div><div class="card"><h2>Risk özeti</h2><div class="grid4">${[['Operasyon',num(i.operasyonRiski)],['Teknik borç',num(i.teknikBorc)],['Bakım baskısı',num(i.bakimBaskisi)],['Ödenemeyen',money(i.odenemeyenGider)],['Temerrüt',int(i.temerrutSayisi)],['Kredi notu',int(i.krediNotu)],['Tarihsel gider',money(i.toplamIsletmeGideri)],['Yatırım',money(i.toplamYatirimHarcamasi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div></div>`}
function val(k){const e=document.querySelector(`[data-key="${CSS.escape(k)}"]`);return e?e.value:(S.drafts.get(k)??'')}function nval(k){const x=Number(val(k));if(!Number.isFinite(x))throw new Error('Sayısal değer geçersiz.');return x}function findService(id){const h=serviceList().find(x=>`${x.hizmetKimligi}@${x.hizmetSurumu}`===id);if(!h)throw new Error('Hizmet bulunamadı.');return h}function findProduct(id){const p=(S.d?.isletim?.urunler||[]).find(x=>x.urunKimligi===id);if(!p)throw new Error('Ürün bulunamadı.');return p}
async function run(b,job){if(S.busy)return;S.busy=true;$('#busy').classList.add('on');const old=b.textContent;b.disabled=true;b.textContent='İşleniyor…';try{const r=await job();toast(r.aciklama||'Tamamlandı.');await refresh(true)}catch(e){toast(e.message,false)}finally{S.busy=false;b.disabled=false;b.textContent=old;$('#busy').classList.remove('on')}}async function action(b){const a=b.dataset.action,id=b.dataset.id||'';await run(b,async()=>{if(a==='service-price'){const h=findService(id);return req('/api/hizmet/fiyat',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,yeniFiyat:nval(`svc:${id}:price`)})}if(a==='service-toggle'){const h=findService(id);return req('/api/hizmet/durum',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,aktif:!h.aktif})}if(a==='service-cap'){const h=findService(id);return req('/api/hizmet/kapasite',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,eklenecekKapasite:nval(`svc:${id}:cap`)})}if(a==='investment')return req('/api/yatirim',{yatirimTuru:id});if(a==='loan')return req('/api/kredi',{krediTuru:id,tutar:nval(`loan:${id}`)});if(a==='app-publish')return req('/api/uygulama/yayinla',{uygulamaKimligi:id,fiyatlandirmaModeli:val(`app:${id}:model`),abonelikUcreti:nval(`app:${id}:sub`),kullanimBasinaUcret:nval(`app:${id}:use`)});if(a==='product-save'){const p=findProduct(id);return req('/api/uygulama/guncelle',{urunKimligi:id,abonelikUcreti:nval(`prd:${id}:sub`),kullanimBasinaUcret:nval(`prd:${id}:use`),aktif:p.aktif})}if(a==='product-cap')return req('/api/uygulama/kapasite',{urunKimligi:id,eklenecekKapasite:nval(`prd:${id}:cap`)});if(a==='distribution')return req('/api/uygulama/dagitim',{urunKimligi:id,isletimSistemiKimligi:val(`dist:${id}:os`),baglantiProtokoluKimligi:val(`dist:${id}:proto`),aktifOlmasiIsteniyor:val(`dist:${id}:active`)==='true'});if(a==='protocol-publish'){const [pid,sur]=id.split('@');return req('/api/protokol/yayinla',{protokolKimligi:pid,surum:sur,lisansModeli:val(`proto:${id}:model`),benimsemeBedeli:nval(`proto:${id}:adopt`),tickLisansBedeli:nval(`proto:${id}:tick`)})}if(a==='protocol-adopt')return req('/api/protokol/benimse',{protokolKimligi:id});if(a==='contract')return req('/api/sozlesme/kabul',{teklifKimligi:id});if(a==='password')return req('/api/parola',{eskiParola:val('account:old'),yeniParola:val('account:new')});throw new Error('Bilinmeyen işlem.')})}
document.addEventListener('input',e=>{const k=e.target?.dataset?.key;if(k)S.drafts.set(k,e.target.value)});document.addEventListener('change',e=>{const k=e.target?.dataset?.key;if(k)S.drafts.set(k,e.target.value)});document.addEventListener('focusout',()=>{setTimeout(()=>{if(!editing()&&S.pending){const d=S.pending;S.pending=null;S.d=d;renderAll(d)}},30)});document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b)});$('#login').onclick=login;$('#logout').onclick=logout;$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});(async()=>{try{await refresh(true);showApp();poll()}catch{}})();
</script></body></html>
""";
}
